CREATE OR REPLACE FUNCTION public.sg_fill_lead_source_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    BEGIN
      IF NEW.slug IS NULL OR btrim(NEW.slug) = '' THEN
        NEW.slug := sg_slugify_lead_source_name(NEW.name);
      END IF;
      IF NEW.sort_order IS NULL THEN
        NEW.sort_order := 99;
      END IF;
      RETURN NEW;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.sg_fill_lead_source_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE
      v_source_id uuid;
    BEGIN
      IF NEW.source_id IS NOT NULL THEN
        RETURN NEW;
      END IF;

      INSERT INTO lead_sources (organization_id, name, slug, sort_order)
      VALUES (NEW.organization_id, 'Autre', 'autre', 99)
      ON CONFLICT (organization_id, slug)
      DO UPDATE SET name = COALESCE(lead_sources.name, EXCLUDED.name)
      RETURNING id INTO v_source_id;

      NEW.source_id := v_source_id;
      RETURN NEW;
    END;
    $function$
